{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "That may be a negotiating starting point for ordinary warranty claims, but it should not cover all claims."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reject the de minimis and tipping basket as drafted."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Seek longer periods for general claims"
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Do not subject title or capacity to the general cap, basket or 18-month period."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Seek separate, materially higher or uncapped protection for fraud, deliberate concealment, title and capacity, and agreed specific indemnities."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "General data-room and public-register disclosure should not qualify warranties."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Limit any knowledge exclusion to actual knowledge of specifically identified Buyer deal-team members after reasonable inquiry"
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require the executed consent and satisfaction or waiver of every associated condition before Completion"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Require repayment and irrevocable discharge of all related security at or before Completion, with lender evidence and delivery of release documents."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "They should be paid or specifically adjusted for at Completion, with no leakage or post-Completion surprise to the Buyer."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "The indemnity should cover failure to obtain title, infringement or third-party claims, and related loss—not merely the stated payment."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require full investigation and remediation, preservation of evidence, timely regulatory/individual notifications where required, and continuing disclosure."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "ensure they are included in working capital or other agreed price adjustments where appropriate."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "The Seller says limitations, exclusive remedy and non-reliance apply to all claims. Reject that breadth."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "The share register at DD-012 is evidence of the Seller’s recorded holding, not a substitute for the Seller’s warranty of good title."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Tax, IP and other material risk areas should have tailored protection rather than being swept into the general regime."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

